-- FTCConnect seed: 112 active New Jersey FTC teams.
-- Source: FTCScout API (mirrors official FIRST team registration data), pulled 2026-10-17.
-- Included teams competed in 2025-26 DECODE and/or are registered for 2026-27 events,
-- and either have a verified-working website or are within 20 miles of Edison, NJ.
-- Contact links fall back to the team's FTCScout page when no working website exists.
-- Safe to re-run: existing seeded rows are updated in place. Run supabase.sql first.

on conflict (team_number) where user_id is null do update set
  name = excluded.name,
  description = excluded.description,
  address = excluded.address,
  apply_link = excluded.apply_link,
  lat = excluded.lat,
  lng = excluded.lng;
